-- Reduced starter bank: arrays + linked lists, EASY -> FAANG_BAR. Slugs key the coaching templates.
INSERT INTO problems (slug, title, category, difficulty, statement) VALUES
('two-sum', 'Two Sum', 'ARRAYS', 'EASY',
 'Given an array of integers nums and an integer target, return the indices of the two numbers that add up to target. Exactly one solution exists and you may not use the same element twice.'),
('best-time-to-buy-and-sell-stock', 'Best Time to Buy and Sell Stock', 'ARRAYS', 'EASY',
 'Given an array prices where prices[i] is the price of a stock on day i, choose one day to buy and a later day to sell to maximise profit. Return the maximum profit, or 0 if no profit is possible.'),
('contains-duplicate', 'Contains Duplicate', 'ARRAYS', 'EASY',
 'Given an integer array nums, return true if any value appears at least twice, and false if every element is distinct.'),
('maximum-subarray', 'Maximum Subarray', 'ARRAYS', 'MEDIUM',
 'Given an integer array nums, find the contiguous subarray with the largest sum and return that sum.'),
('product-of-array-except-self', 'Product of Array Except Self', 'ARRAYS', 'MEDIUM',
 'Given an integer array nums, return an array answer such that answer[i] equals the product of all elements of nums except nums[i]. Solve without division and in O(n) time.'),
('three-sum', '3Sum', 'ARRAYS', 'MEDIUM',
 'Given an integer array nums, return all unique triplets [a, b, c] such that a + b + c == 0. The solution set must not contain duplicate triplets.'),
('trapping-rain-water', 'Trapping Rain Water', 'ARRAYS', 'HARD',
