('reverse-linked-list', 'Reverse Linked List', 'LINKED_LISTS', 'EASY',
 'Given the head of a singly linked list, reverse the list and return the new head.'),
('merge-two-sorted-lists', 'Merge Two Sorted Lists', 'LINKED_LISTS', 'EASY',
